+//! Blob-side wiring for the shared British Fencing licence.
+//!
+//! The domain model, repository, and migration planner live in the
+//! [`fencer_licence`](::fencer_licence) crate. This module is the `blob`
+//! facade: it holds the collection handle usage, GET `/user/me` hydration,
+//! the write path used by the v3 membership route, and the one-shot
+//! per-user → shared migration.
+
+use anyhow::Result;
+use chrono::Utc;
+use ids::{FencerId, TypedId, UserId};
+use tracing::{info, warn};
+
+use crate::db::DB;
+use crate::v2::model::User;
+
+pub use ::fencer_licence::{
+  FencerLicenceFields, MigrationDecision, MigrationPlan, PerUserAssertion, document_id,
+  plan_migration, repository,
+};
+
+/// Loads the shared membership id for `fencer_id`. `None` covers never-set,
+/// explicitly cleared, and a missing document.
+pub async fn get_membership_id(fencer_id: &TypedId<FencerId>) -> Result<Option<String>> {
+  repository::get_membership_id(&DB.fencer_british_licences, fencer_id).await
+}
+
+/// Last-write-wins set or clear, recording who wrote and when. Never logs
+/// the membership id itself.
+pub async fn set_licence(
+  fencer_id: &TypedId<FencerId>,
+  membership_id: Option<String>,
+  set_by: &TypedId<UserId>,
+) -> Result<()> {
+  let clearing = membership_id.is_none();
+  repository::upsert(
+    &DB.fencer_british_licences,
+    fencer_id.clone(),
+    membership_id,
+    set_by.clone(),
+    Utc::now(),
+  )
+  .await?;
+  if clearing {
+    info!(
+      fencer_id = %fencer_id,
+      set_by = %set_by,
+      "Cleared shared British Fencing licence"
+    );
+  } else {
+    info!(
+      fencer_id = %fencer_id,
+      set_by = %set_by,
+      "Updated shared British Fencing licence"
+    );
+  }
+  Ok(())
+}
+
+/// Overwrites each tracked fencer's `british_fencing_licence` on `user` with
+/// the shared record, for the GET `/user/me` response. Does not persist;
+/// the user document is no longer the source of truth.
+///
+/// A failure to load the shared licences degrades to `None` for every
+/// tracked fencer rather than failing the request: the rest of the user
+/// profile (tracked fencers, preferences, capabilities) must stay available
+/// even when the licence sidecar collection is having a blip, matching how
+/// `view::standings::fencer::licence_for_fencer` degrades on the read path.
+pub async fn hydrate_user(user: &mut User) -> Result<()> {
+  let fencer_ids: Vec<_> = user
+    .fields
+    .tracked_fencers
+    .iter()
+    .map(|tracked| tracked.fencer_id.clone())
+    .collect();
+  let by_fencer =
+    match repository::get_membership_ids(&DB.fencer_british_licences, &fencer_ids).await {
+      Ok(by_fencer) => by_fencer,
+      Err(err) => {
+        warn!(
+          error = ?err,
+          "Failed to load shared British Fencing licences; omitting from user profile"
+        );
+        Default::default()
+      }
+    };
+  for tracked in &mut user.fields.tracked_fencers {
+    tracked.british_fencing_licence = by_fencer.get(&tracked.fencer_id).cloned().flatten();
+  }
+  Ok(())
+}
+
+#[derive(Debug, Clone, Default, PartialEq, Eq)]
+pub struct MigrationCounts {
+  pub adopted: usize,
+  pub conflicted: usize,
+  pub skipped_already_shared: usize,
+  pub users_stripped: usize,
+}
+
+/// Walks every user's tracked fencers and collects each historical per-user
+/// licence assertion. Pure: no I/O, so it is exercised directly in tests
+/// rather than only indirectly through the planner it feeds.
+fn collect_assertions(users: &[User]) -> Vec<PerUserAssertion> {
+  let mut assertions = Vec::new();
+  for user in users {
+    let user_id = TypedId::<UserId>::database(&user.id);
+    for tracked in &user.fields.tracked_fencers {
+      if let Some(membership_id) = &tracked.british_fencing_licence {
+        assertions.push(PerUserAssertion {
+          user_id: user_id.clone(),
+          fencer_id: tracked.fencer_id.clone(),
+          membership_id: membership_id.clone(),
+        });
+      }
+    }
+  }
+  assertions
+}
+
+/// Nulls `british_fencing_licence` on every tracked fencer not in
+/// `keep_fencer_ids`, returning the updated user only if that changed
+/// anything. Fencers in `keep_fencer_ids` are left untouched: a conflicted
+/// fencer's competing per-user assertions are the only record of the
+/// conflict, and stripping them before a human reconciles it would destroy
+/// that record with no way to recover it.
+fn strip_licence_except(
+  user: &User,
+  keep_fencer_ids: &std::collections::HashSet<TypedId<FencerId>>,
+) -> Option<User> {
+  let mut updated = user.clone();
+  let mut changed = false;
+  for tracked in &mut updated.fields.tracked_fencers {
+    if tracked.british_fencing_licence.is_some() && !keep_fencer_ids.contains(&tracked.fencer_id) {
+      tracked.british_fencing_licence = None;
+      changed = true;
+    }
+  }
+  changed.then_some(updated)
+}
+
+/// Lifts per-user `TrackedFencer.british_fencing_licence` values onto the
+/// shared collection, then strips the per-user field from every user
+/// document that still carries it. Idempotent: a fencer that already has a
+/// shared record is not overwritten (a live last-write-wins value wins
+/// over the historical assertion). Conflicted fencers (multiple distinct
+/// per-user assertions, no shared value adopted) are left unstripped so a
+/// human can still see and reconcile the competing values.
+pub async fn migrate_per_user_licences() -> Result<MigrationCounts> {
+  let users = crate::v2::user::get_all_users().await?;
+  let assertions = collect_assertions(&users);
+
+  let plan = plan_migration(&assertions);
+  let existing = repository::list_all(&DB.fencer_british_licences).await?;
+  let already: std::collections::HashSet<TypedId<FencerId>> = existing
+    .into_iter()
+    .map(|doc| doc.fields.fencer_id)
+    .collect();
+
+  let mut counts = MigrationCounts {
+    adopted: 0,
+    conflicted: 0,
+    skipped_already_shared: 0,
+    users_stripped: 0,
+  };
+  let now = Utc::now();
+  let mut conflicted_fencer_ids = std::collections::HashSet::new();
+
+  for decision in &plan.decisions {
+    match decision {
+      MigrationDecision::Adopt {
+        fencer_id,
+        membership_id,
+        set_by,
+      } => {
+        if already.contains(fencer_id) {
+          counts.skipped_already_shared += 1;
+          continue;
+        }
+        repository::upsert(
+          &DB.fencer_british_licences,
+          fencer_id.clone(),
+          Some(membership_id.clone()),
+          set_by.clone(),
+          now,
+        )
+        .await?;
+        counts.adopted += 1;
+      }
+      MigrationDecision::Conflict {
+        fencer_id,
+        distinct_count,
+      } => {
+        warn!(
+          fencer_id = %fencer_id,
+          distinct_count,
+          "Skipping shared British Fencing licence migration; multiple distinct per-user assertions"
+        );
+        conflicted_fencer_ids.insert(fencer_id.clone());
+        counts.conflicted += 1;
+      }
+    }
+  }
+
+  for user in &users {
+    if let Some(updated) = strip_licence_except(user, &conflicted_fencer_ids) {
+      DB.users.patch_document(user, &updated).await?;
+      crate::v2::user::invalidate_user_cache(&user.id).await;
+      counts.users_stripped += 1;
+    }
+  }
+
+  info!(
+    adopted = counts.adopted,
+    conflicted = counts.conflicted,
+    skipped_already_shared = counts.skipped_already_shared,
+    users_stripped = counts.users_stripped,
+    "British Fencing licence migration finished"
+  );
+  Ok(counts)
+}
+
+#[cfg(test)]
+mod tests {
+  use super::*;
+  use crate::v2::model::{ResultsBackfillStatus, UserFields, UserPersonalInfo};
+  use ids::Identified;
+  use std::collections::HashSet;
+
+  fn tracked(fencer_id: &str, licence: Option<&str>) -> crate::v2::model::TrackedFencer {
+    crate::v2::model::TrackedFencer {
+      fencer_id: TypedId::<FencerId>::usaf(fencer_id),
+      results_backfill: ResultsBackfillStatus::default(),
+      british_fencing_licence: licence.map(str::to_string),
+    }
+  }
+
+  fn user(id: &str, tracked_fencers: Vec<crate::v2::model::TrackedFencer>) -> User {
+    Identified {
+      id: id.to_string(),
+      partition: Some("flunge".to_string()),
+      fields: UserFields {
+        primary_user: UserPersonalInfo {
+          email: format!("{id}@example.com"),
+          name: None,
+          cell: None,
+        },
+        observers: vec![],
+        tracked_fencers,
+        fencer_relationships: vec![],
+        travel_plans: vec![],
+        connections: None,
+        google_needs_reauth: false,
+        clerk_user_id: None,
+        image_url: None,
+        capabilities: vec![],
+        groups: vec![],
+        preferences: Default::default(),
+        family_group_id: None,
+      },
+    }
+  }
+
+  #[test]
+  fn collect_assertions_ignores_fencers_with_no_licence() {
+    let users = vec![user("alice", vec![tracked("100", None)])];
+    assert!(collect_assertions(&users).is_empty());
+  }
+
+  #[test]
+  fn collect_assertions_collects_one_per_asserting_user_and_fencer() {
+    let users = vec![
+      user("alice", vec![tracked("100", Some("142013"))]),
+      user(
+        "bob",
+        vec![tracked("100", Some("142013")), tracked("200", Some("999"))],
+      ),
+    ];
+    let assertions = collect_assertions(&users);
+    assert_eq!(assertions.len(), 3);
+    assert!(
+      assertions
+        .iter()
+        .any(|a| a.user_id.to_string() == "u.d.alice"
+          && a.fencer_id.to_string() == "f.u.100"
+          && a.membership_id == "142013")
+    );
+    assert!(assertions.iter().any(|a| a.user_id.to_string() == "u.d.bob"
+      && a.fencer_id.to_string() == "f.u.200"
+      && a.membership_id == "999"));
+  }
+
+  #[test]
+  fn strip_licence_except_returns_none_when_nothing_to_strip() {
+    let alice = user("alice", vec![tracked("100", None)]);
+    assert_eq!(strip_licence_except(&alice, &HashSet::new()), None);
+  }
+
+  #[test]
+  fn strip_licence_except_nulls_licence_fields_not_in_keep_set() {
+    let alice = user("alice", vec![tracked("100", Some("142013"))]);
+    let updated = strip_licence_except(&alice, &HashSet::new()).expect("should strip");
+    assert_eq!(
+      updated.fields.tracked_fencers[0].british_fencing_licence,
+      None
+    );
+  }
+
+  #[test]
+  fn strip_licence_except_leaves_conflicted_fencers_untouched() {
+    let fencer_id = TypedId::<FencerId>::usaf("100");
+    let mut keep = HashSet::new();
+    keep.insert(fencer_id.clone());
+    let alice = user(
+      "alice",
+      vec![tracked("100", Some("142013")), tracked("200", Some("999"))],
+    );
+    let updated = strip_licence_except(&alice, &keep).expect("should strip the non-conflicted one");
+    assert_eq!(
+      updated.fields.tracked_fencers[0].british_fencing_licence,
+      Some("142013".to_string())
+    );
+    assert_eq!(
+      updated.fields.tracked_fencers[1].british_fencing_licence,
+      None
+    );
+  }
+}
