@@ -0,0 +1,75 @@
+use chrono::{DateTime, Utc};
+use serde::{Deserialize, Serialize};
+
+use ids::{DEFAULT_ID_DETAIL, FencerId, HasIdDetail, IdDetail, TypedId, UserId};
+
+/// Shared British Fencing membership id for one fencer, plus who last set it
+/// and when. `membership_id: None` is an explicit clear: the document stays
+/// so a wrong value is traceable rather than silently deleted.
+#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
+#[serde(rename_all = "camelCase")]
+pub struct FencerLicenceFields {
+  pub fencer_id: TypedId<FencerId>,
+  #[serde(default, skip_serializing_if = "Option::is_none")]
+  pub membership_id: Option<String>,
+  pub set_by: TypedId<UserId>,
+  pub set_at: DateTime<Utc>,
+}
+
+impl FencerLicenceFields {
+  pub fn new(
+    fencer_id: TypedId<FencerId>,
+    membership_id: Option<String>,
+    set_by: TypedId<UserId>,
+    set_at: DateTime<Utc>,
+  ) -> Self {
+    Self {
+      fencer_id,
+      membership_id,
+      set_by,
+      set_at,
+    }
+  }
+}
+
+impl HasIdDetail for FencerLicenceFields {
+  fn id_detail(&self) -> &IdDetail {
+    &DEFAULT_ID_DETAIL
+  }
+}
+
+#[cfg(test)]
+mod tests {
+  use super::*;
+
+  #[test]
+  fn omitted_membership_id_round_trips_as_none() {
+    let json = r#"{
+      "fencerId": "f.u.123",
+      "setBy": "u.d.alice",
+      "setAt": "2026-09-04T00:00:00Z"
+    }"#;
+    let fields: FencerLicenceFields = serde_json::from_str(json).unwrap();
+    assert_eq!(fields.membership_id, None);
+    let serialized = serde_json::to_value(&fields).unwrap();
+    assert!(serialized.get("membershipId").is_none());
+  }
+
+  #[test]
+  fn membership_id_round_trips() {
+    let fields = FencerLicenceFields::new(
+      TypedId::<FencerId>::usaf("123"),
+      Some("142013".to_string()),
+      TypedId::<UserId>::database("alice"),
+      DateTime::parse_from_rfc3339("2026-09-04T00:00:00Z")
+        .unwrap()
+        .with_timezone(&Utc),
+    );
+    let serialized = serde_json::to_value(&fields).unwrap();
+    assert_eq!(serialized["membershipId"], "142013");
+    assert_eq!(serialized["fencerId"], "f.u.123");
+    assert_eq!(serialized["setBy"], "u.d.alice");
+    let back: FencerLicenceFields = serde_json::from_value(serialized).unwrap();
+    assert_eq!(back, fields);
+  }
+}
