/// Gets the capability configuration document, creating a default one if it doesn't exist.
pub async fn get_capability_config() -> Result<CapabilityConfigDoc> {
  let result = DB.config.get_document(CAPABILITY_CONFIG_ID).await?;

  if let Some(config) = result {
    Ok(config)
  } else {
    // Create default config
    let default_config = Identified {
      id: CAPABILITY_CONFIG_ID.to_string(),
      partition: Some("flunge".to_string()),
      fields: CapabilityConfigFields::default(),
    };
    DB.config.upsert_document(default_config.clone()).await?;
    Ok(default_config)
  }
}

#[cfg(test)]
mod tests {
  use super::*;

  fn parse_patch(json: &str) -> Patch {
    serde_json::from_str(json).unwrap()
  }

  #[test]
  fn validate_user_patch_paths_rejects_capabilities_changes() {
    let patch = parse_patch(r#"[{"op":"replace","path":"/capabilities","value":[]}]"#);
    let result = validate_user_patch_paths(&patch, false);
    assert!(result.is_err());
    assert!(
      result
        .unwrap_err()
        .to_string()
        .contains("cannot modify their own capabilities")
    );
  }

  #[test]
  fn validate_user_patch_paths_rejects_groups_changes() {
    let patch = parse_patch(r#"[{"op":"add","path":"/groups/0","value":"beta"}]"#);
    let result = validate_user_patch_paths(&patch, false);
    assert!(result.is_err());
    assert!(
      result
        .unwrap_err()
        .to_string()
        .contains("cannot modify their own groups")
    );
  }

  #[test]
  fn validate_user_patch_paths_rejects_tracked_fencer_changes_when_lockdown_enabled() {
    let patch =
      parse_patch(r#"[{"op":"add","path":"/trackedFencers/-","value":{"fencerId":"f.u.123"}}]"#);
    let result = validate_user_patch_paths(&patch, true);
    assert!(result.is_err());
    assert!(
      result
