    assert!(validate_user_patch_paths(&patch, true).is_ok());
  }

  #[test]
  fn initial_backfill_status_blocks_when_tab_results_missing() {
    let status = initial_backfill_status_for_capabilities(&[], Utc::now());
    assert_eq!(status.state, ResultsBackfillState::BlockedOnCapability);
    assert_eq!(status.requested_at, None);
  }

  #[test]
  fn initial_backfill_status_queues_when_tab_results_present() {
    let requested_at = Utc::now();
    let status =
      initial_backfill_status_for_capabilities(&[UserCapability::TabResults], requested_at);
    assert_eq!(status.state, ResultsBackfillState::Queued);
    assert_eq!(status.requested_at, Some(requested_at));
  }

  #[test]
  fn enqueue_blocked_backfills_transitions_only_blocked_entries() {
    let now = Utc::now();
    let preexisting_requested_at = now - chrono::Duration::minutes(10);
    let mut tracked = vec![
      TrackedFencer {
        fencer_id: ViewTypedId::<FencerId>::usaf("123"),
        results_backfill: ResultsBackfillStatus::blocked_on_capability(),
        british_fencing_licence: None,
      },
      TrackedFencer {
        fencer_id: ViewTypedId::<FencerId>::usaf("456"),
        results_backfill: ResultsBackfillStatus::queued(preexisting_requested_at),
        british_fencing_licence: None,
      },
    ];

    enqueue_blocked_backfills(&mut tracked, now);

    assert_eq!(
      tracked[0].results_backfill.state,
      ResultsBackfillState::Queued
    );
    assert_eq!(tracked[0].results_backfill.requested_at, Some(now));
    assert_eq!(
      tracked[1].results_backfill.state,
      ResultsBackfillState::Queued
    );
    assert_eq!(
      tracked[1].results_backfill.requested_at,
      Some(preexisting_requested_at)
    );
  }

