  fn same_fencer_id_matches_identical_view_ids() {
    let left = ViewTypedId::<FencerId>::usaf("12345");
    let right = ViewTypedId::<FencerId>::usaf("12345");
    assert!(same_fencer_id(&left, &right));
  }

  #[test]
  fn relationship_for_fencer_mut_finds_matching_entry() {
    let target = ViewTypedId::<FencerId>::usaf("999");
    let mut relationships = vec![
      FencerRelationship {
        fencer_id: ViewTypedId::<FencerId>::usaf("111"),
        following: true,
        notify: true,
        competition_history: Vec::new(),
        display: None,
      },
      FencerRelationship {
        fencer_id: target.clone(),
        following: false,
        notify: true,
        competition_history: Vec::new(),
        display: None,
      },
