  }
}

/// Updates the rollout configuration for a specific capability.
pub async fn set_capability_rollout(rollout: CapabilityRollout) -> Result<CapabilityConfigDoc> {
  let mut config = get_capability_config().await?;

  // Find and update existing, or add new
  let existing_idx = config
    .fields
    .capabilities
    .iter()
    .position(|c| c.capability == rollout.capability);

  match existing_idx {
    Some(idx) => config.fields.capabilities[idx] = rollout,
    None => config.fields.capabilities.push(rollout),
  }

  DB.config.upsert_document(config.clone()).await?;

  // Invalidate the capability config cache
  crate::v2::capabilities::invalidate_capability_config_cache().await;

  Ok(config)
}

