/// Gets a summary of all groups and user counts.
pub async fn get_groups_summary() -> Result<Vec<GroupSummary>> {
  let users = get_all_users().await?;
  let mut group_counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();

  for user in users {
    for group in user.fields.groups {
      *group_counts.entry(group).or_insert(0) += 1;
    }
  }

  let mut summaries: Vec<GroupSummary> = group_counts
    .into_iter()
    .map(|(name, user_count)| GroupSummary { name, user_count })
    .collect();

  summaries.sort_by(|a, b| a.name.cmp(&b.name));
  Ok(summaries)
}

