  /// module's shared per-fencer fetch (`crate::recommendations::standings::
  /// fetch_fencer_standings`) can log this id from call sites that only hold
  /// the response, not the fencer id that produced it.
  pub(crate) fencer_id: TypedId<FencerId>,
  /// `false` when this fencer's id could not be resolved to a USA Fencing
  /// identity (a non-USAF-system id with no linked USAF membership number).
  /// Distinguishes "no current standings" from "standings could not be
  /// looked up": `standings` may still contain British items when this is
  /// `false`, because those are matched by British Fencing licence rather
  /// than USA Fencing identity. An empty `standings` with
  /// `identity_resolved: true` is a confirmed lack of any current standing.
  pub(crate) identity_resolved: bool,
  /// `pub(crate)` so the recommendations Standings contributor module
  /// (`crate::recommendations::standings`) can reuse this endpoint's own
  /// fetch + enrichment logic instead of re-deriving it against
  /// `standings_index` directly.
  pub(crate) standings: Vec<FencerStandingItem>,
}

