  pub(crate) entrants: Option<usize>,
  /// The capture task's cached comparison with the prior week. Its absence is
  /// meaningful: no history is not the same as a flat standing.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) movement: Option<MovementSummary>,
  /// Unified source provenance. This is absent for legacy National and
  /// Regional rows, whose caches do not carry an atomic snapshot's freshness
  /// metadata. Its optional timestamps remain explicit `null` fields when a
  /// Unified source lacks them, matching the Unified list response.
  #[serde(flatten, skip_serializing_if = "Option::is_none")]
  pub(crate) unified: Option<UnifiedStandingItemMetadata>,
