/// Snapshot provenance shared by every snapshot-backed standings source.
/// Both Unified and British populate the identical
/// `sourceUpdatedAt`/`fetchedAt`/`isStale` trio against the same
/// [`super::SOURCE_STALE_AFTER`] threshold. Flattened at both sites, so each
/// source's wire keys stay top-level; the Unified wire shape is byte-for-byte
/// unchanged -- see
/// `unified_response_projects_private_rows_and_preserves_source_metadata`
/// and `source_freshness_flatten_matches_prior_unified_wire_shape` below.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct SourceFreshness {
  pub(crate) source_updated_at: Option<i64>,
  pub(crate) fetched_at: Option<i64>,
  pub(crate) is_stale: Option<bool>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct UnifiedStandingItemMetadata {
  #[serde(flatten)]
  pub(crate) freshness: SourceFreshness,
  /// USA Fencing's own list code (e.g. `SNRWS`), mirroring the Unified list
  /// envelope's `source.listCode`. This is the code clients must render on a
  /// Unified chip: `classifier.code` diverges from it for Senior individual
  /// events, since `EventCategory::Senior::code()` returns the team-shaped
  /// `"STM"` regardless of whether the standing is individual or team.
  pub(crate) list_code: Option<String>,
  /// The server-owned launch marker. `false` remains explicit when the
  /// runtime flag is off; it never removes the Unified standing itself.
  pub(crate) is_new: bool,
  /// Mirrors the Unified list endpoint's per-row `pointsFloor`: `Some` when
  /// this fencer's `points` is a minimum tied to their weapon rating rather
  /// than earned from `counted` results.
  #[serde(skip_serializing_if = "Option::is_none")]
  pub(crate) points_floor: Option<unified_snapshot::PointsFloor>,
